	if len(sidecars) == 0 {
		return
	}

	nodeID := s.cfg.p2p.NodeID()
	custodyGroupCount, err := s.cfg.p2p.CustodyGroupCount()
	if err != nil {
		log.WithError(err).Error("Failed to get custody group count")
		return
	}

