// No ommer/uncle hash validation exists in Prysm's P2P validation layer.
// The block passes through validateBeaconBlockPubSub() which performs:
// - Signature verification
// - Slot checks
// - Parent block checks
// - KZG commitment length checks
// But NO explicit ommers_hash == EMPTY_OMMER_HASH validation.
// Ommer validation is entirely delegated to the execution client via engine_newPayload API.

=== Items 3, 4, 5: beacon-chain/state/state-native/state_trie.go ===
// NOTE: Prysm's beacon state uses SSZ HashTreeRoot (Merkle tree), NOT EL Patricia Merkle Trie.
// The "patricialize" function referenced in the checklist items is part of the Python execution-specs
// (go-ethereum), NOT in Prysm. Prysm is a CL client.

func (b *BeaconState) HashTreeRoot(ctx context.Context) ([32]byte, error) {
    ctx, span := trace.StartSpan(ctx, "beaconState.HashTreeRoot")
    defer span.End()

    b.lock.Lock()
    defer b.lock.Unlock()
    if err := b.initializeMerkleLayers(ctx); err != nil {
        return [32]byte{}, err
    }
    if err := b.recomputeDirtyFields(ctx); err != nil {
        return [32]byte{}, err
    }
    return bytesutil.ToBytes32(b.merkleLayers[len(b.merkleLayers)-1][0]), nil
}

func (b *BeaconState) initializeMerkleLayers(ctx context.Context) error {
    if len(b.merkleLayers) > 0 {
        return nil
    }
    fieldRoots, err := ComputeFieldRootsWithHasher(ctx, b)
    if err != nil {
        return err
    }
    layers := stateutil.Merkleize(fieldRoots)
    b.merkleLayers = layers
    // ... resets dirtyFields per version
    return nil
}

func (b *BeaconState) recomputeDirtyFields(ctx context.Context) error {
    for field := range b.dirtyFields {
        root, err := b.rootSelector(ctx, field)
        if err != nil {
            return err
        }
        idx := field.RealPosition()
        b.merkleLayers[0][idx] = root[:]
        b.recomputeRoot(idx)
        delete(b.dirtyFields, field)
    }
    return nil
}

// stateutil.Merkleize - pads leaves to multiple of 32, then builds Merkle tree
func Merkleize(leaves [][]byte) [][][]byte {
    hashFunc := hash.CustomSHA256Hasher()
    layers := make([][][]byte, ssz.Depth(uint64(len(leaves)))+1)
    for len(leaves)%32 != 0 {
        leaves = append(leaves, make([]byte, 32))
    }
    currentLayer := leaves
    layers[0] = currentLayer
    i := 1
    for len(currentLayer) > 1 && i < len(layers) {
        layer := make([][]byte, 0)
        for i := 0; i < len(currentLayer); i += 2 {
            hashedChunk := hashFunc(append(currentLayer[i], currentLayer[i+1]...))
            layer = append(layer, hashedChunk[:])
        }
        currentLayer = layer
        layers[i] = currentLayer
        i++
    }
    return layers
}

// CopyAllTries - copies field tries to remove shared references
func (b *BeaconState) CopyAllTries() {
    b.lock.Lock()
    defer b.lock.Unlock()

    for fldIdx, fieldTrie := range b.stateFieldLeaves {
        if fieldTrie.FieldReference() != nil {
            fieldTrie.Lock()
            if fieldTrie.FieldReference().Refs() > 1 {
                fieldTrie.FieldReference().MinusRef()
                newTrie := fieldTrie.CopyTrie()
                b.stateFieldLeaves[fldIdx] = newTrie
            }
            fieldTrie.Unlock()
        }
    }
}

